import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"西溪易說卷六","description":"西溪易說 - 西溪易說卷六","frontmatter":{"title":"西溪易說卷六","description":"西溪易說 - 西溪易說卷六"},"headers":[],"relativePath":"classics/xixi/007.md","filePath":"classics/xixi/007.md"}'),i={name:"classics/xixi/007.md"};function r(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="西溪易說卷六" tabindex="-1">西溪易說卷六 <a class="header-anchor" href="#西溪易說卷六" aria-label="Permalink to “西溪易說卷六”">​</a></h1><p>欽定四庫全書</p><p>宋李過撰</p><p>䷙ 乾下艮上 「大畜」，</p><p>「大畜」：利貞。不家食，吉。利涉大川。彖曰：「大畜」，剛健。篤實輝光，日新其德。剛上而尚賢，能止健，大正也。「不家食，吉」，養賢也。「利涉大川」，應乎天也。「大畜」、「小畜」，皆止健也。「小畜」，臣畜君；「大畜」，君畜民。以臣畜君，當用「巽」止。君之於民，可以令行而禁止之也，故用「艮」止。五方之民皆有性，凡有血氣者皆有爭心，天下之健固難畜也，必有道以貞守之，故曰「利貞，不家食，吉」。賢者然後不家食，畜道成，則舉天下皆不家食之賢者也。堯舜比屋皆可封之民，成周之世人人皆有士君子之行，則「不家食」之謂也。彖曰：「大畜」，剛健。「大畜」，天下之剛健也。「篤實輝光，日新其德」，畜健之道也。大凡血氣之剛與理義之剛相對，「日新其德」，理義既勝，則血氣之強自消。故聖人止健，只就「日新其德」上著工夫。「剛上而尚賢」，謂上九也。以九居上，畜道成矣。有賢德之可尚，止健之道，至此「大正」也。「不家食吉」，養賢也。天下皆可養之賢也。「利涉大川」，應乎天也。謂畜道既濟，則應天而亨也。</p><p>象曰：天在山中，「大畜」；君子以多識前言往行，以畜其德。天在山中，天地發生之意。山中之天常在後，天陽一敷，無物不暢，而窮山絕谷之中猶凝然。蓋涸陰沍寒之地，許多陽氣為積陰所斬，未得發達也。此天在山中，為「止健」之象。君子觀此，多識前言往行，以畜其德，大其所蘊畜而不遽發，一發則沛然矣。猶之山中包含許多生意，積陰既散，發生之意不可御矣。古詩「人間四月芳菲盡，山寺桃花始盛開」，即此理也。</p><p>初九，有厲，利已。象曰：「有厲利已」，不犯災也。</p><p>六爻皆以畜健為義，自初而上，以漸而畜，畜而至上九，畜道乃成，故初「有厲」，二「說輻」，三「馬逐」。此三爻健體，畜之頗用力。四「童牛」，五「豶豕」，二爻陰體也，受畜矣。上九何天，畜道成矣，不假畜矣。初畜之始，健體欲動，必戒之曰：動則有危難，且宜止也，以災厲而恐懼之也。初能受畜，故不犯災矣。</p><p>九二，輿說輻。象曰：「輿說輻」，中無尤也。</p><p>二健欲動，如車有輪，為說其輻，使不得行。二得中，亦能受畜，故曰「中無尤」也。小畜亦說輻，然以臣畜君，則犯堂陛之分，故說輻必反曰大畜。君畜民，可以令行而禁止之，故說輻則受畜。</p><p>九三，良馬逐，利艱貞。曰閒輿衛，利有攸往。象曰：「利有攸往」，上合志也。</p><p>畜健至三，受畜者半矣，而未受畜者猶半也。「良馬逐」，未受畜者也，如良馬之逐逐然，則宜以「艱貞」之道止之。「閒輿衛」，已受畜者也，班閒其輿衛而不進，則宜與之往。此聖人抑揚之道，正如由也兼人，故退之；求也退，故進之。象曰：「利有攸往」，上合志也。謂「閒輿衛」者，志與上合，故得與進也。</p><p>六四：童牛之牿，元吉。象曰：六四「元吉」，有喜也。</p><p>畜而至四，以六居之，其性柔矣。良馬之性，畜為童牛，牛性順，童牛又順者，然未免觸，故以木牿其角而後馴。變乾為順，畜之易矣，故「元吉」而「喜」。</p><p>六五：豶豕之牙，吉。象曰：六五之「吉」，有慶也。</p><p>畜至於五，柔而得中，畜道成矣。「豶豕」，去勢之豕也。豕既去勢，不復躑躅以就馴養。四之童牛未免加牿，五之豶豕並牿去之，其性熟矣。不惟有喜，又有慶也。</p><p>上九：何天之衢，亨。象曰：「何天之衢」，道大行也。</p><p>畜而至此，畜道亨矣。四通八達，防閒不立，而天下相忘於道術之中，如「何天之衢」然，了無窒礙也。所謂「千年古道萬年堤，老牯馴馴不解迷。牧子不知何處去，亂山芳草鷓鴣啼」是也。象曰：道大行也。畜道至此而後大行，古者所謂大同之世也。如堯舜之世，康衢之童子，擊壤之老人，皆天衢中瑞物也。䷚ 震下艮上 「頤」，</p><p>此卦先儒說頤之理亦貫，但卦爻不相屬。</p><p>頤：貞吉，觀頤，自求口實。彖曰：「頤，貞吉」，養正則吉也。「觀頤」，觀其所養也。「自求口實」，觀其自養也。天地養萬物，聖人養賢以及萬民，頤之時大矣哉。</p><p>上下二陽，中四陰，外實中虛，頤之象也。卦：艮上震下，艮止震動，上止而下動，亦頤之象也。「頤」，養也。頤之飲食，所以養體也。曰：</p><p>「頤，貞吉。觀頤，自求口實」。彖：「頤，貞吉」。人生有口體之累，孰不求養？然得之必有道，故曰「養正則吉也」。有大人之養，有小人之養。養其大體，則為大人；養其小體，則為小人。觀其所養，觀其所從養也。飲食不可自外求之，求所以得飲食之道，求在我者也。故曰：「自求口實，觀其自養也。」從而推之，天地養萬物，聖人養賢以及萬民，則頤之時大矣哉。六爻一陽在上，為頤之主，上體止而下體動以應之，故下之求食者皆由上而得，故上為「由頤」。然口容貴止不貴動，上三爻止而皆吉，下三爻勤而皆兇。</p><p>象曰：山下有雷，「頤」；君子以慎言語，節飲食。</p><p>山下有雷，蟄雷也。震在下，艮止之，故為蟄雷。復卦雷在地中，上體順，陽動於下而以順行。此卦上體止，陽動於下而艮止，一畫止之，其聲閉而不能出，故在「復」為雷之動，在「頤」為雷之蟄。夫雷所以發號令而施潤澤也，今蟄于山下，號令不發而潤澤不施，是天地之口閉也。君子體此以自養，天不發號令，故謹言語；天不施潤澤，故節飲食。</p><p>初九，舍爾靈龜，觀我朵頤，兇。象曰：「觀我朵頤」，亦不足貴也。</p><p>六爻貴止不貴動。口之飲食，上止而下動。初九在頤下，「震」體，動，求飲食之人也。靈龜，心也；「朵頤」，口也。常謂人曰：舍汝養心之道，而觀我養口體，故兇。飲食之人，人賤之，故曰「不足貴」。六二，顛頤，拂經，於丘頤，徵兇。象曰：六二「徵兇」，行失類也。二當上應，丘近初，反隨下體之動，故曰「顛頤」。拂，逆也；經，正也。五在上居艮，丘頤也，二應之正也，逆正而從下，故曰「拂經於丘頤」。以此而往，兇也。象曰：「行失類也」，拂上從下，失其黨類也。</p><p>六三，拂頤，貞兇。十年勿克用，無攸利。象曰：「十年勿用」，道大悖也。</p><p>三當應上，九居上體，為頤之主，應之正也。三亦拂之而隨下體之動，以正言之，「兇」也。志求飲食，為人所惡，至於十年而不見用。三取上隔互體「坤」，「坤」數十，故曰「十年」。既不為上用，何利之有！象曰：「十年勿用」，道大悖也。</p><p>六四，顛頤，吉。虎視耽耽，其欲逐逐，無咎。象曰：「顛頤」之吉，上施光也。</p><p>四居上體，與初為應，亦曰「顛頤」。然四艮體，止於上，而初以動應之，故「吉」。蓋己不求人而人求我也。「虎視耽耽，其欲逐逐」，四居上位，如虎之據而視下，其狀貌耽耽然，而所欲物逐逐以奔赴之。己之威嚴不失也，何咎！象曰：上施光也。以居上體而所施光大也。</p><p>六五：拂經，居貞吉。不可涉大川。象曰：「居貞」之吉，順以從上也。</p><p>五正當應二，以二從初，故「拂經」而「居貞」，自止其所也，止則吉。然居五不為頤之主，下無與，不可以濟難，故曰「不可涉大川」。象曰「以從上也」，言舍二而從上也。上九：由頤，厲吉。利涉大川。象曰：「由頤厲吉」，大有慶也。以九處上，為頤之主，體純止，天下之求養者皆由之以成功，故曰「由頤」。如人之頤然，上體不全，則下雖動而無所應，飲食之道廢矣。然居上位危，將應天下之求，能危懼則吉，故曰「厲吉」。下皆從之，可以濟難，故曰「利涉大川」。象曰：大有慶也。頤之功成，故「大有慶」。天地養萬物，聖人養賢及萬民，功用全屬此爻。䷛ 巽下兌上 大過，大過棟橈。利有攸往，亨。彖曰：大過，大者過也。「棟橈」，本末弱也。剛過而中，巽而說行，「利有攸往」，乃亨。大過之時大矣哉。</p><p>剛過乎陰，大者過也。天下之理，惟中而已，安可過也？然有過而後中者，君子之時中也。卦中六爻，陽雖過而陽得中，故雖過而可用。古之聖人有行之者，湯武之君也。湯武之過，不害為湯武之中。周公之兄弟，周公之過也，不害為周公之中，所為過而中也。然太過必曰「棟橈」，卦中四陽在中，上下皆柔，猶之棟柱然，中實而上下橈也。六爻分明有此象。古之聖人有不得已而於過中取中者，皆出於橈敗之世。故湯武處君臣之變，然後以弒君為中；周公處兄弟之變，然後以殺兄弟為中。彼其犯大義，虧人倫而不顧者，其所遇然也。使所處者在平世，安用過以取中哉？故大過必曰「棟橈」。曰「利有攸往亨」者，不以橈敗而止也，必求所以濟橈敗者，往則亨也。彖曰：「大過」，大者過也；謂陽過也。「棟橈」，本末弱也。謂上下皆柔也。剛過而中，巽而說行。以六爻言之，剛雖過而二五得中；以二卦之義言之，則下「巽」而上說。以此而行，宜可以濟，故往而「亨」也。當大過之時，而不往求濟，是聽其橈敗而委之無可奈何也。自古聖人，固有以身當天下之變者，蓋因時而制宜也，故曰：「大過之時大矣哉！」全卦之象，上下皆橈，故曰「棟橈」。分上下卦而觀之，上卦上橈而下實，下實則猶可立，故四居上卦之下，而曰「棟隆吉」；下卦下橈而上實，下橈則上必傾，故三居下卦之上，而曰「棟橈」。他爻不取棟象，而三、四爻取者，分上下體而言也。初爻言過謹，上爻言過勇，二、五言陰陽之過，三、四言「棟橈」，此六爻之大略也。</p><p>象曰：澤滅木，大過，君子以獨立不懼，遁世無悶。</p><p>木在地上，水在澤中，常理也。今以澤水氾濫而滅木，是大過之象也。君子觀此所以「大過」於人者，「獨立不懼，遁世無悶」而已。蓋水無常滅木之理，水勢衰則木見矣，君子所以貴於獨立也。</p><p>初六，藉用白茅，無咎。象曰：「藉用白茅」，柔在下也。</p><p>一柔在四陽之下，以柔藉剛，猶以茅藉物然過乎謹也，過謹又何咎？繫辭「苟錯諸地可矣」，藉之用茅，何咎之有？慎之至也。夫茅之為物薄，而用可重也，慎斯術也以往，其無所失矣！</p><p>九二，枯楊生稊，老夫得其女妻，無不利。象曰：「老夫」「女妻」，過以相與也。二應五而得兌，「兌」為少女，老夫得其女妻也。陽過乎陰，雖過無害，故象曰「過以相與也」。</p><p>九三，棟橈，兇。象曰：「棟撓」之兇，不可以有輔也。</p><p>下卦上實而下弱，下弱則上傾，故三居下卦之上而曰「棟橈兇」。象曰「不可以有輔也」，言下弱而無助也。</p><p>九四，棟隆，吉。有它吝。象曰：「棟隆」之吉，不橈乎下也。上卦上弱而下實，下實則可載，故四居上卦之下而曰「棟隆吉」。橈在上六，非己吝，故曰「有他吝」。象曰「不橈乎下也」，謂下實也。此二爻當分上下體看。</p><p>九五：枯楊生華，老婦得其士夫，無咎無譽。象曰：「枯楊生華」，何可久也？「老婦士夫」，亦可醜也。</p><p>五應二而得「巽」，「巽」為長女，「老婦得其士夫」也。陰過乎陽，不能生育，故象曰「亦可醜也」。卦止二女，疑無夫象。與頤對，值頤卦震下，震為長男，故下卦對之為「老夫」。頤卦上艮，艮為少男，故上卦對之為「士夫」。</p><p>上六：過涉滅頂，兇，無咎。象曰：「過涉」之兇，不可咎也。六居澤上，澤方滅木，而已欲過涉。過而滅頂，過乎勇也，故「兇」。然無咎者，可以死勇，無害也。求仁於井，固不可陷。君臣之難，義在必死，則冒白刃，蹈水火，不可已也。捨生取義，何畏滅頂？象曰「不可咎也」，言過涉之不可罪也。設此義以為逃難偷生者之戒。䷜ 坎下坎上 坎</p><p>習坎，有孚，維心亨。行有尚。彖曰：「習坎」，重險也。水流而不盈，行險而不失其信。「維心，亨」，乃以剛中也。「行有尚」，往有功也。天險不可升也，地險山川丘陵也。王公設險以守其國。險之時用大矣哉！</p><p>「習」，重也；「坎」，險也。上下皆「坎」，險難之極也。然坎之德，中實而有孚，故能濟險難者，亦必如坎也。何以見之？「坎」為水。水之為水，日流而不息，既盈而復進，至於海，然後得水之平。其未至海也，歷險多矣，雖瞿塘、灩澦不辭也。故天下善出險，無如水。人之處險難，能如水之不息，則何難之不濟？自止於心，則無可亨之理矣。故曰：「有孚，維心，亨，行有尚。」象曰：「水流而不盈，行險而不失其信。」水之流，不以盈而止，盈則復往矣。其行險也，日以繼夜，未嘗少息也。故有信莫如水，此坎之所以為「有孚」也。「維心，亨」，乃以剛中也。坎能出險，以其中實以心而亨也。六爻，二雖剛中，在重坎之下，故「求小得」，未能出「坎」也。九五剛中處「坎」上卦，其險可出。全卦之德盡屬五，然一陽陷二陰之間，亦未能出也。以有坎之德，方在濟險，則無咎，然亦未出險也。故卦辭雲「行有尚」，而彖曰「往則有功也」。天險不可升也，地險山川丘陵也。王公設險以守其國，險之時用大矣哉！夫險固難也，而用險之功亦不可無也。築城鑿池，背山阻河，亦所以固國也。恃險而不修德，固不可；恃德而不修險，亦大不可，故夫子於彖言之。</p><p>象曰：水瀳至，習坎；君子以常德行，習教事。</p><p>「瀳至」，相繼而至也。君子處「坎」，如水之流，則出「坎」矣。「常德行，習教事」，所當盡其在我者也。曰「常」曰「習」，乃不息之功也。</p><p>初六，習坎，入於坎窞，兇。象曰：「習坎」入「坎」，失道兇也。處重坎之下，「坎」貴乎出，而初入「坎」，宜其兇也。今水之先流者入「坎」，後至者出「坎」。入「坎」而盈，既盈而出者至海，而入者在「坎」，是先至者為後至者之藉也。初在先，故入坎。象曰：「失道兇」，違行而失道，所以「兇」也。</p><p>九二，坎有險，求小得。象曰：「求小得」，未出中也。</p><p>二、五，君臣也。二遠君而在下，非能共謀以濟者，為國守險以俟時平可也，故曰：「坎有險，求小得，不可大用也。」象曰「未出中也」，以在重坎之中，未能出也。如張巡、許遠所處，乃為國守險者也。</p><p>六三，來之坎坎，險且枕，入於坎窞，勿用。象曰：「來之坎坎」，終無功也。</p><p>三處一坎又一「坎」。來，「來之坎坎」也。處險又枕險，雖在下卦之上，猶在上卦之下，是為上一坎之藉也，故亦入坎而不可用。象曰「終無功也」，三不中正，非有常德，故終坎而無功。</p><p>六四，樽酒簋貳，用缶，納約自牖，終無咎。象曰：「樽酒簋貳」，剛柔際也。</p><p>九五為濟難之君，四近君，為腹心共濟之臣，投機之會，間不容髮。腹心之臣非他人比，相與謀惟密而不洩。禮不必備，止以「樽酒」；不容他人，惟陳簋；器不必文，用缶而已。不可庭議，自牖納約。坎難之時，君臣交際，固當如此。正如宋藝祖夜半冒雪幸大臣之第，以議南征北伐之計，熾炭燒肉，普妻行酒而已。君臣相遇如此，何難不濟！</p><p>九五，坎不盈，祗既平，無咎。象曰：「坎不盈」，中未大也。五，濟難之君也。「有孚維心」，亨全在五，如水流而不盈，行險而不失其信者，然後可以去難，故曰「坎不盈」，不以盈坎而止也。須止於既平，然後無咎。如水至於海，既得水之平，然後其流息也。蓋當患難之世，天下之才何限，智者思獻謀，勇者思效力，惟患人主無平難之心。苟有其心，天下莫不與也。象曰：「中未大也」，謂五在險中，方圖濟險，尚未能光大也。</p><p>上六，系用徽纆，置於叢棘，三歲不得，兇。象曰：上六失道，兇三歲也。</p><p>上六處坎之上，其難深矣，如被繩縳，又墜於叢棘之中，無可出之理也。至於三歲之久，而竟不得脫，蓋已應在三，越三爻以求援，又入於坎窞，故曰「三歲不得，兇」。象曰：上六失道，兇三歲也。蓋以柔居上，非濟難之才，故不能出坎。䷝ 離下離上</p><p>離，</p><p>離：利貞，亨。畜牝牛吉。彖曰：離，麗也。日月麗乎天，百穀草木麗乎土，重明以麗乎正，乃化成天下。柔麗乎中正，故亨。是以「畜牝牛吉」也。</p><p>據此一卦，乃重明繼離之象。卦辭、彖辭與大象皆極善。而六爻之變，三為日昃之辭，四又「死如棄如」，六五正重明之主也，乃「出涕戚嗟」，重明之義安在？前輩以「出涕戚嗟」為謙恭，夫謙恭可也，安用涕哭為哉？殊不知重明之象，以明繼明，文王於此為萬世定立君之法，盡在於是，惟夫子知之。彖、象所釋，其辭甚嚴，先儒皆未之能察也。蓋唐、虞禪，夏後、殷、周繼。夫繼世以子，三代共之，而立子必以嫡，此又聖人立一定不易之之法，萬世莫能改也。故文王於此六爻中詳之，上下二體皆重明繼離也。 原闕。 西溪易說卷六，</p>',61)])])}const x=a(i,[["render",r]]);export{m as __pageData,x as default};
